            case Direction.EAST -> AssemblerBlock.box((double)0.1, (double)0.1, (double)0.1, (double)15.9, (double)14.0, (double)15.9);
            case Direction.WEST -> AssemblerBlock.box((double)0.1, (double)0.1, (double)0.1, (double)15.9, (double)14.0, (double)15.9);
        };
